import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconArrow, IconCheck } from "./icons";

/** Curated game titles available as one-click server images in the catalog. */
const TITLES: { name: string; tag: string; family: string; glyph: string; from: string; to: string }[] = [
  { name: "Minecraft", tag: "Java & Bedrock", family: "minecraft", glyph: "⛏️", from: "#3b6d1f", to: "#6aab3a" },
  { name: "Valheim", tag: "Dedicated world", family: "valheim", glyph: "🪓", from: "#284c6f", to: "#4a86b8" },
  { name: "Rust", tag: "High player counts", family: "rust", glyph: "🔧", from: "#8a3b1e", to: "#cd6a37" },
  { name: "Palworld", tag: "Co-op survival", family: "palworld", glyph: "🐾", from: "#0f6f69", to: "#25c0b4" },
  { name: "CS2", tag: "Competitive FPS", family: "cs2", glyph: "🎯", from: "#8a5a12", to: "#e0a63a" },
  { name: "Terraria", tag: "Sandbox worlds", family: "terraria", glyph: "🌳", from: "#3a5a2a", to: "#7aa441" },
];

const PERKS = ["Deploy in minutes", "Low-latency network", "Full root & mods", "Scale players anytime"];

function GamepadIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M7 10v4M5 12h4M15 11h.01M18 13h.01" />
      <path d="M17.3 6H6.7A4.7 4.7 0 0 0 2 10.7c-.3 2.2-.8 4-.9 5.6-.1 1.6 1 2.7 2.4 2.7 1.2 0 1.8-.7 2.5-1.6l.7-.9a2 2 0 0 1 1.6-.8h4.4a2 2 0 0 1 1.6.8l.7.9c.7.9 1.3 1.6 2.5 1.6 1.4 0 2.5-1.1 2.4-2.7-.1-1.6-.6-3.4-.9-5.6A4.7 4.7 0 0 0 17.3 6z" />
    </svg>
  );
}

/** Game-server hosting showcase — one-click titles with hover-lift + glow. */
export function GameServers() {
  return (
    <div className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-900/60 p-6 backdrop-blur-md sm:p-10">
      <div
        className="pointer-events-none absolute inset-0 opacity-70"
        style={{
          backgroundImage:
            "radial-gradient(ellipse 50% 60% at 15% 0%, rgba(111,71,245,0.16), transparent), radial-gradient(ellipse 45% 60% at 90% 100%, rgba(34,211,238,0.12), transparent)",
        }}
      />
      <div className="relative grid gap-10 lg:grid-cols-[0.85fr_1.15fr] lg:items-center">
        <div>
          <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/10 px-3 py-1.5 text-xs font-semibold text-brand-300">
            <GamepadIcon />
            Game server hosting
          </span>
          <h3 className="mt-5 text-2xl font-bold tracking-tight sm:text-3xl">
            Spin up a <span className="grad-text">game server</span> in a click
          </h3>
          <p className="mt-4 max-w-md text-slate-400">
            One-click deployment for the games your community loves — deploy in minutes on
            low-latency NVMe hardware with full root and mod support. No config marathons.
          </p>
          <ul className="mt-6 grid grid-cols-2 gap-x-6 gap-y-2.5">
            {PERKS.map((p) => (
              <li key={p} className="inline-flex items-center gap-2 text-sm text-slate-300">
                <span className="flex h-[18px] w-[18px] items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                  <IconCheck size={12} />
                </span>
                {p}
              </li>
            ))}
          </ul>
          <Link href="/register" className="btn-primary mt-8 px-6 py-3 text-base">
            Launch a game server
            <IconArrow size={16} />
          </Link>
        </div>

        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          {TITLES.map((t, i) => (
            <Reveal key={t.name} delay={i * 55}>
              <div className="group flex h-full flex-col gap-2 rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4 transition-all duration-200 hover:-translate-y-1 hover:border-brand-500/30 hover:shadow-[0_12px_30px_-14px_rgb(111_71_245_/_0.6)]">
                <span
                  className="flex h-12 w-12 items-center justify-center rounded-xl text-[26px] leading-none shadow-[inset_0_1px_1px_rgba(255,255,255,0.25),0_6px_16px_-8px_rgba(0,0,0,0.6)] transition-transform duration-200 group-hover:scale-105"
                  style={{ backgroundImage: `linear-gradient(135deg, ${t.from}, ${t.to})` }}
                >
                  <span aria-hidden>{t.glyph}</span>
                </span>
                <span className="mt-1 text-sm font-semibold text-white">{t.name}</span>
                <span className="text-[11px] text-slate-500">{t.tag}</span>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </div>
  );
}

